const staticData = $getWorkflowStaticData('global');
staticData.sessions ??= {};
const item = $input.first().json;
const sessionId = item.sessionId || 'default';
const MAX_MESSAGES = 24;
const MAX_AGE_MS = 24 * 60 * 60 * 1000;
const MAX_DAILY_TOKENS = 1000000;
const today = new Date().toISOString().slice(0, 10);

staticData.usage ??= { date: today, tokens: 0 };
if (staticData.usage.date !== today) staticData.usage = { date: today, tokens: 0 };

if (staticData.usage.tokens >= MAX_DAILY_TOKENS) {
  return [{ json: { ...item, budgetExceeded: true, output: 'Hoy he alcanzado mi limite de conversacion y necesito descansar. Vuelve manana y seguimos hablando con calma.' } }];
}

for (const key of Object.keys(staticData.sessions)) {
  if (Date.now() - staticData.sessions[key].ts > MAX_AGE_MS) delete staticData.sessions[key];
}

if (!staticData.sessions[sessionId]) staticData.sessions[sessionId] = { ts: Date.now(), msgs: [] };
const session = staticData.sessions[sessionId];
session.ts = Date.now();

session.msgs.push({ role: 'user', content: String(item.chatInput ?? '') });
while (session.msgs.length > MAX_MESSAGES) session.msgs.shift();

const messages = [{ role: 'system', content: item.systemPrompt }, ...session.msgs];
return [{ json: { ...item, messages } }];

const staticData = $getWorkflowStaticData('global');
staticData.sessions ??= {};
const item = $input.first().json;
const sessionId = $('Memoria').first().json.sessionId || 'default';
const reply = item.choices?.[0]?.message?.content;

if (reply) {
  if (!staticData.sessions[sessionId]) staticData.sessions[sessionId] = { ts: Date.now(), msgs: [] };
  staticData.sessions[sessionId].msgs.push({ role: 'assistant', content: String(reply) });
  while (staticData.sessions[sessionId].msgs.length > 24) staticData.sessions[sessionId].msgs.shift();
}

const used = item.usage?.total_tokens ?? 0;
if (used > 0) {
  const today = new Date().toISOString().slice(0, 10);
  staticData.usage ??= { date: today, tokens: 0 };
  if (staticData.usage.date !== today) staticData.usage = { date: today, tokens: 0 };
  staticData.usage.tokens += used;
}

return [{ json: item }];

const SECRET = 'PEGA_AQUI_TU_SECRETO';
if (String($input.first().json.auth ?? '') !== SECRET) {
  throw new Error('No autorizado');
}
return [$input.first()];
